-- Phase 6-8 additive migration for chat, interviews, productivity, analytics, notifications, and exports.
DO $$ BEGIN CREATE TYPE "ConversationRole" AS ENUM ('USER','ASSISTANT','SYSTEM'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "InterviewType" AS ENUM ('TECHNICAL','HR','BEHAVIORAL','RESUME','CAREER'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "Difficulty" AS ENUM ('EASY','MEDIUM','HARD'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "JobStatus" AS ENUM ('SAVED','APPLIED','INTERVIEW','OFFER','REJECTED','WITHDRAWN'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "GoalStatus" AS ENUM ('NOT_STARTED','IN_PROGRESS','COMPLETED','PAUSED'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "NotificationType" AS ENUM ('GOAL_REMINDER','INTERVIEW_REMINDER','RESUME_REMINDER','CAREER_ANALYSIS_REMINDER','SYSTEM'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "ExportType" AS ENUM ('CAREER_REPORT','ATS_REPORT','LEARNING_ROADMAP','INTERVIEW_REPORT','JOB_TRACKER_SUMMARY'); EXCEPTION WHEN duplicate_object THEN null; END $$;
DO $$ BEGIN CREATE TYPE "ExportFormat" AS ENUM ('PDF','JSON'); EXCEPTION WHEN duplicate_object THEN null; END $$;

CREATE TABLE IF NOT EXISTS "Conversation" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Conversation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Conversation_userId_updatedAt_idx" ON "Conversation"("userId","updatedAt");
CREATE TABLE IF NOT EXISTS "Message" ("id" TEXT NOT NULL PRIMARY KEY,"conversationId" TEXT NOT NULL,"role" "ConversationRole" NOT NULL,"content" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Message_conversationId_createdAt_idx" ON "Message"("conversationId","createdAt");
CREATE TABLE IF NOT EXISTS "InterviewSession" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"type" "InterviewType" NOT NULL,"difficulty" "Difficulty" NOT NULL,"targetRole" TEXT,"status" TEXT NOT NULL DEFAULT 'COMPLETED',"summary" TEXT,"performanceScore" INTEGER,"confidenceScore" INTEGER,"feedback" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InterviewSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "InterviewSession_userId_createdAt_idx" ON "InterviewSession"("userId","createdAt");
CREATE TABLE IF NOT EXISTS "InterviewQuestion" ("id" TEXT NOT NULL PRIMARY KEY,"sessionId" TEXT,"type" "InterviewType" NOT NULL,"difficulty" "Difficulty" NOT NULL,"question" TEXT NOT NULL,"expectedAnswer" TEXT,"tags" TEXT[] DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InterviewQuestion_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "InterviewSession"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "InterviewQuestion_sessionId_idx" ON "InterviewQuestion"("sessionId");
CREATE TABLE IF NOT EXISTS "InterviewFeedback" ("id" TEXT NOT NULL PRIMARY KEY,"sessionId" TEXT NOT NULL,"question" TEXT,"answer" TEXT,"feedback" TEXT NOT NULL,"suggestions" TEXT[] DEFAULT ARRAY[]::TEXT[],"score" INTEGER NOT NULL,"confidenceScore" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InterviewFeedback_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "InterviewSession"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "JobApplication" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"company" TEXT NOT NULL,"role" TEXT NOT NULL,"location" TEXT,"source" TEXT,"status" "JobStatus" NOT NULL DEFAULT 'SAVED',"appliedAt" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "JobApplication_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "JobApplication_userId_status_idx" ON "JobApplication"("userId","status");
CREATE TABLE IF NOT EXISTS "CareerResource" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"type" TEXT NOT NULL,"url" TEXT,"provider" TEXT,"description" TEXT,"targetCareer" TEXT,"tags" TEXT[] DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "CareerResource_type_idx" ON "CareerResource"("type");
CREATE TABLE IF NOT EXISTS "Goal" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"status" "GoalStatus" NOT NULL DEFAULT 'NOT_STARTED',"deadline" TIMESTAMP(3),"progress" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Goal_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Goal_userId_status_idx" ON "Goal"("userId","status");
CREATE TABLE IF NOT EXISTS "GoalMilestone" ("id" TEXT NOT NULL PRIMARY KEY,"goalId" TEXT NOT NULL,"title" TEXT NOT NULL,"completed" BOOLEAN NOT NULL DEFAULT false,"dueDate" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "GoalMilestone_goalId_fkey" FOREIGN KEY ("goalId") REFERENCES "Goal"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "Notification" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"type" "NotificationType" NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"read" BOOLEAN NOT NULL DEFAULT false,"dueAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "Notification_userId_read_idx" ON "Notification"("userId","read");
CREATE TABLE IF NOT EXISTS "AnalyticsSnapshot" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"metrics" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AnalyticsSnapshot_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "AnalyticsSnapshot_userId_createdAt_idx" ON "AnalyticsSnapshot"("userId","createdAt");
CREATE TABLE IF NOT EXISTS "ExportHistory" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"type" "ExportType" NOT NULL,"format" "ExportFormat" NOT NULL,"fileName" TEXT,"payload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExportHistory_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "ExportHistory_userId_createdAt_idx" ON "ExportHistory"("userId","createdAt");
